// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        bytes32 expected = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        bool ok;
        vm.prank(caller);
        try c.proxiableUUID() returns (bytes32 actual) {
            ok = actual == expected;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
